<script setup lang="ts">
const { data, refresh } = await useWorkspace()
const modal = ref(false), busy = ref(false), error = ref(''), search = ref('')
const form = reactive({ name: '', source: 'huggingface', reference: '', family: 'whisper' })
const filtered = computed(() => data.value.models.filter(m => `${m.name} ${m.reference}`.toLowerCase().includes(search.value.toLowerCase())))
async function save() { busy.value = true; error.value = ''; try { await $fetch('/api/models', { method: 'POST', body: form }); await refresh(); modal.value = false; useNotice().notify('Model added to your library'); form.name = ''; form.reference = '' } catch (e) { error.value = apiError(e) } finally { busy.value = false } }
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR STARTING POINT</span><h1>Model library<span class="title-dot">.</span></h1><p>Choose a foundation. Make it your own.</p></div><button class="button primary" @click="modal = true; error = ''"><AppIcon name="Plus" />Add model</button></div><div class="toolbar"><span class="section-count">{{ data.models.length }} models</span><label class="search-box"><AppIcon name="Search" :size="17"/><input v-model="search" aria-label="Search models" placeholder="Search models…" /></label></div><div v-if="filtered.length" class="resource-grid"><article v-for="model in filtered" :key="model.id" class="panel resource-card"><div class="resource-top"><span class="resource-icon purple"><AppIcon name="Layers" :size="25" /></span><span class="pill">{{ model.family }}</span></div><h2>{{ model.name }}</h2><p class="mono break-word">{{ model.reference }}</p><div class="model-capabilities"><span><AppIcon name="AudioLines" :size="14" />Speech recognition</span><span>LoRA</span></div><div class="resource-footer"><span>{{ model.source === 'huggingface' ? 'Hugging Face' : 'Worker-local directory' }}</span><NuxtLink :to="{ path: '/runs/new', query: { model: model.id } }" class="text-link">Train<AppIcon name="ArrowUpRight" :size="15" /></NuxtLink></div></article></div><section v-else class="panel"><EmptyState icon="Layers" :title="search ? 'No matching models' : 'Meet your next base model'" :description="search ? 'Try a different model name or reference.' : 'Add a Whisper model from Hugging Face or a directory on your training worker.'"><button v-if="!search" class="button secondary" @click="modal = true">Add your first model<AppIcon name="Plus" :size="16" /></button></EmptyState></section><div class="info-strip bottom-info"><AppIcon name="GitBranch" /><span>Whisper is the first supported model family. Additional architectures will use their own training recipes.</span></div><AppModal v-if="modal" title="Add a base model" subtitle="The worker loads the model when training starts." @close="modal = false"><form @submit.prevent="save"><label class="field">Display name<input v-model="form.name" required minlength="2" maxlength="100" placeholder="Whisper large v3" /></label><label class="field">Source<select v-model="form.source"><option value="huggingface">Hugging Face</option><option value="local">Directory on worker</option></select></label><label class="field">{{ form.source === 'huggingface' ? 'Model repository ID' : 'Absolute model directory' }}<input v-model="form.reference" required :placeholder="form.source === 'huggingface' ? 'openai/whisper-large-v3' : '/models/whisper-large-v3'" /></label><p class="form-hint">Choose a complete Whisper base model, not an adapter-only folder. Private models use the worker’s HF_TOKEN.</p><p v-if="error" class="alert error" role="alert">{{ error }}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal = false">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Saving…' : 'Add model' }}</button></div></form></AppModal></template>
